# -*- coding: utf-8 -*-
"""Blog posts, group m: cloudy sealer (blushing) and the restore-or-replace decision for old pavers."""
from _helpers import page, capsule, sec, table, faq, ul, steps, note, cta, a, svc, city, cs, post, compare, src, ext, price, per, tel, contact

EUCLID = "https://euclidchemical.com/company/blog/archive/diagnosing-5-common-concrete-sealer-problems/"
DIRECT = "https://directcolors.com/blogs/dcu/how-to-fix-concrete-sealer"


def p_paver_sealer_turned_white_or_cloudy():
    body = "".join([
        sec("What Does It Mean When Paver Sealer Turns White or Cloudy?",
            f"<p>A white, milky or cloudy look under a sealer is almost always moisture or too much film, not a defect in the paver. Solvent-based acrylics are the usual victims. The coating cured over water, or cured so thick that the solvent couldn't escape, and the trapped moisture and air scatter light so the finish looks white. "
            f"Installers call it blushing. It's the most common reason homeowners phone about a {svc('paver-sealing', 'paver sealing')} job that looked perfect for a day or two.</p>"
            f"<p>Four different problems get lumped under \"white,\" and they don't share a fix: blushing, efflorescence, a heavy buildup of coats, and a sealer that doesn't suit the paver or the previous coat. Sorting out which one you have is most of the work, because the wrong treatment on the wrong problem makes it worse.</p>"),
        sec("Why Is Florida So Hard on Sealer?",
            f"<p>Florida gives sealer three things it dislikes: damp air, a damp slab and afternoon rain. Orlando's airport averages 51.45 inches of rain a year and Sarasota–Bradenton's about 49.05 inches (NOAA 1991–2020), and most of it falls between late May and mid-October, so the dry window is narrower than the calendar suggests. "
            f"One sealer maker calls the dew-point margin the cause of more failures than anything else ({ext(DIRECT, 'Direct Colors, how to fix concrete sealer')}), which fits what happens on a still Gulf-coast evening: the surface cools below the dew point and a film of water forms under a coat that's still wet.</p>"
            f"<p>Irrigation adds to it. A sprinkler zone that runs at 5 a.m. can soak the paver edge and the joint sand that a crew sealed the afternoon before. Pavers are porous and sand joints hold water, so moisture keeps rising to the surface for hours after the visible damp is gone. "
            f"A sealer applied over that doesn't have anywhere to let it out except through the film.</p>"),
        sec("What Are the Four Causes of a White Look?",
            "<p>Each cause leaves a slightly different fingerprint. This table is the short version; the sections below explain how to tell them apart.</p>"
            + table("Common reasons sealed pavers look white or cloudy", ["Cause", "What it looks like", "What's behind it", "Usual remedy"],
                    [["Blushing", "Milky haze across the sealed surface, worse on humid mornings", "Water trapped under or in a solvent-based coat", "Dry out, then re-flow with the maker's solvent product"],
                     ["Efflorescence", "Chalky, crystalline white, often patchy or around edges", "Salts carried up from the paver or base by water", "Wait, then a paver cleaner; seal only when dry"],
                     ["Too-thick buildup", "White film that peels or flakes, usually on an older, repeatedly sealed surface", "Coats stacked past what the pavers can release moisture through", "Strip and reseal thin"],
                     ["Incompatible product", "Cloudy or sticky patches where a new coat sits over a different old one", "Water-based over solvent, or the reverse, without a test", "Test patch first, strip if it fails"]],
                    "Blushing and buildup are sealer problems; efflorescence is a paver problem that shows through the sealer.")
            + f"<p>On the second row, {post('efflorescence-on-pavers-and-concrete', 'the guide to efflorescence on pavers and concrete')} covers where those salts come from and why they can appear months after installation. ICPI's Tech Spec 5 describes the deposit as whitish calcium carbonate that doesn't affect the pavers' structural performance or durability.</p>"),
        sec("How Can You Tell Which One You Have?",
            f"<p>Start with timing, then look at where the white sits. White that appeared within a few days of sealing, covers most of the surface evenly and gets worse on muggy mornings points to blushing. "
            f"Chalky patches at the edges, around downspouts or at the bottom of a slope, that you can see in the unsealed joint sand too, point to efflorescence. White film on a surface sealed several times, which has started to flake at the corners, points to buildup.</p>"
            f"<p>Weather is a useful clue. Direct Colors notes that haze getting worse on humid days points to moisture, while milky haze together with water stains or efflorescence points to a problem coming up from the slab. "
            f"A sealer maker's own guidance also describes a plastic-sheet moisture check before recoating, and a test patch of the maker's repair product on a hidden square foot or two. Both are cheap, and both settle an argument that a guess can't.</p>"
            + ul(["<strong>Hasn't been sealed yet and it's white:</strong> that's efflorescence, not sealer.",
                  "<strong>White within days, even, humid-day worse:</strong> likely blushing.",
                  "<strong>Old, thick, flaking:</strong> buildup, which a re-flow won't fix.",
                  "<strong>Sticky or patchy after a recoat with a different product:</strong> compatibility."])
            + "<p>These are field rules of thumb, not a lab result. A sealer's technical data sheet is the authority on its own repair steps, so read it before putting any solvent on the surface.</p>"),
        sec("How Is Cloudy Paver Sealer Fixed, From Least to Most Aggressive?",
            f"<p>Fix it in order of how little it disturbs the surface: wait for dry weather first, re-flow a solvent-based acrylic with the maker's repair product second, and strip and reseal last. "
            f"Moisture-related blushing often clears by itself once the pavers dry and the sun warms them, so jumping straight to chemicals can waste money. The cost of the strip-and-reseal route is covered separately on the {a('/paver-sealing-cost/', 'paver sealing cost page')}.</p>"
            + steps([("Wait and let it dry.", "If the haze is recent and the weather turns dry for several days, check again before doing anything. Keep the sprinklers off the area meanwhile."),
                     ("Re-flow a solvent-based acrylic.", "Direct Colors describes a repair product that \"re-flashes a cured solvent sealer\": confirm the slab is dry, back-roll it in, and allow about 24 hours before traffic. The same source warns it destroys water-based finishes, so identify the sealer first."),
                     ("Strip and reseal.", "Water-based haze can't be re-flashed, per the same source, and neither can haze that survives a re-flow, haze with peeling, or haze that returns. Those need chemical stripping, a thorough clean, a dry-out and fresh sealer in thin coats.")])
            + f"<p>Heat guns and household solvents appear in many online fixes. We wouldn't try them on a whole driveway: too much heat bubbles or browns the coat, and strong solvents have fumes and fire risks that belong to a trained applicator. A small test patch is the right place to experiment.</p>"),
        sec("Is It a DIY Fix or a Restoration Job?",
            f"<p>A small hazy spot on a solvent-based sealer, found the week after sealing, is a reasonable weekend job with the maker's repair product and a respirator. Whole driveways, flaking film, water-based coats and anything stacked over several years belong with a crew set up for {svc('paver-restoration', 'paver restoration')}, because stripping, rinsing out the joint sand and re-sanding is where most of the labor sits.</p>"
            + table("DIY or restoration", ["Situation", "Reasonable DIY?", "Why"],
                    [["Hazy corner after one coat, solvent sealer", "Yes, with a test patch", "Small area, nothing stacked underneath"],
                     ["Whole patio hazy, same week", "Maybe", "A re-flow works if the slab is dry and the coat is thin enough"],
                     ["White and flaking after several coats", "No", "Needs stripping; leftover film makes the next coat fail"],
                     ["White returns after a re-flow", "No", "Points to moisture coming from below the pavers"],
                     ["Unsure whether it's sealer or salts", "Test first", "Treating efflorescence with solvent does nothing"]])
            + "<p>If the white keeps coming back after a re-flow or a strip, the usual suspect is water arriving from underneath. A low spot, a downspout or a tree line can keep the pavers wet, and that's a drainage problem to fix before sealing again.</p>"),
        sec("How Do You Keep Sealer From Turning White Next Time?",
            f"<p>Seal only a dry surface, in a calm temperature window, in thin coats. Euclid's technical guidance says one acrylic coat should go on at about 5 mils wet, roughly 300 square feet per gallon, and warns against applying over wet surfaces or building up coats over the years ({ext(EUCLID, 'Euclid Chemical, diagnosing common sealer problems')}). The label coverage rate is a ceiling, not a target.</p>"
            + ul(["Let the pavers dry for as long as the sealer's data sheet requires after a wash or a heavy rain, and shut off sprinkler zones that reach the area.",
                  "Pick a morning that stays dry through evening, and stop in time that the coat can cure before dew forms.",
                  "Apply thin, even coats, back-rolled, with no puddles in the bevels and low spots.",
                  "Never switch between water-based and solvent-based products without a test patch.",
                  "If the sand joints will be stabilized, finish that step first and follow the maker's cure time."])
            + f"<p>Gloss matters here too. A high-gloss film shows blush more than a natural look does, and {compare('wet-look-vs-natural-paver-sealer', 'the comparison of wet-look and natural-finish sealers')} explains why many Florida homeowners accept the lower sheen. ICPI notes that acrylic sealers last a few years before recoating, so plan the next coat rather than stacking one every season.</p>"),
        sec("Next Step",
            f"<p>If the white hasn't cleared and you can't tell which cause it is, send photos and the sealing date to the unit nearest you, Kissimmee & Greater Orlando at {tel('orlando')} or Sarasota at {tel('sarasota')}. You can also {contact('use the estimate form')}.</p>"),
    ])
    faqs = [
        faq("Can I seal over a white, hazy sealer to hide it?",
            "No. A new coat over trapped moisture seals the problem in and usually makes the haze deeper. Dry or re-flow the existing coat first, or strip it if the maker's repair step doesn't clear it, then apply a thin coat."),
        faq("Will rain right after sealing cause blushing?",
            "It can. Water landing on a solvent-based coat that hasn't cured can be trapped under the film. Many makers give a rain-free window on the data sheet, so check yours and watch the forecast for the day after."),
        faq("Does sealer haze damage the pavers underneath?",
            "Generally no. The haze sits in or under the film, and the pavers themselves aren't harmed. The risk is cosmetic and a film that eventually peels, which is why a persistent haze is worth correcting."),
        faq("Why is only part of my driveway cloudy?",
            "Partial haze often follows moisture patterns: low corners, areas shaded from the sun, runs under roof edges or where a sprinkler hits. Compare the cloudy spots with the wet spots. If they match, moisture is the reason."),
        faq("Is a haze that appears in the morning and fades by afternoon a problem?",
            "Usually a sign of moisture in a coat that's still releasing it. If the haze lessens as the surface warms, waiting a week or two in dry weather may clear it. If it holds all day, test a re-flow patch."),
        faq("Does white haze mean I used the wrong sealer?",
            "Not necessarily. A suitable sealer applied over a damp surface or too thickly can blush. A mismatch between old and new products is a separate cause, and a small test patch tells you quickly."),
    ]
    return page("/blog/paver-sealer-turned-white-or-cloudy/", "post",
                "Paver Sealer Turned White or Cloudy: Causes and Fixes",
                "Paver sealer turned white or cloudy? How to tell blushing from efflorescence and buildup, and fixes from waiting to stripping, as of November 2026.",
                "Why Paver Sealer Turns White or Cloudy in Florida, and How It's Fixed",
                capsule("Sealer that turns white or milky on pavers in Kissimmee, Orlando or Sarasota is usually blushing: moisture trapped under a solvent-based acrylic, or a coat applied too thick. As of November 2026, a recent haze often clears in a few dry days; if not, re-flowing with the maker's repair product or stripping and resealing in thin coats fixes it."),
                body, faqs=faqs,
                sources=[("Euclid Chemical, diagnosing common concrete sealer problems", EUCLID),
                         ("Direct Colors, how to fix concrete sealer", DIRECT), "icpi-ts5"],
                related=[("/paver-sealing/", "Paver sealing"), ("/paver-restoration/", "Paver restoration"),
                         ("/blog/efflorescence-on-pavers-and-concrete/", "Efflorescence on pavers"),
                         ("/compare/wet-look-vs-natural-paver-sealer/", "Wet-look vs natural sealer"),
                         ("/paver-sealing-cost/", "Paver sealing cost")],
                crumbs=[("Blog", "/blog/")], published="2026-11-17", service="paver-sealing", image=None, form=False)


def p_restore_or_replace_old_pavers():
    body = "".join([
        sec("Should You Restore Old Pavers or Replace Them?",
            f"<p>Restore when the pavers themselves are sound and the problem is on top or in a few spots: faded color, stains, lost joint sand, a sunken patch. Replace when the base has failed across large areas, the units are cracking or too thin for the traffic, or the edges keep spreading. "
            f"A crew can usually tell which within an hour of walking the surface, and the first test costs nothing: how much of the field has moved, and why.</p>"
            f"<p>The deciding question is whether the problem is surface wear or base failure. {svc('paver-restoration', 'Paver restoration')} fixes surface wear and spot failures, and it can include lifting an area, rebuilding the base and laying the same pavers back down. Full replacement tears up the field. Those are very different bills.</p>"),
        sec("Is the Problem Surface Wear or a Failed Base?",
            f"<p>Surface wear shows in color and finish and is cosmetic: faded, stained, algae-streaked, joints washed out. A failed base shows in shape: ruts, dips that hold water, pavers rocking underfoot, joints opening along a line. "
            f"ICPI's Tech Spec 2 calls for about 6 inches of compacted aggregate under a residential driveway on well-drained soil and 2–4 inches more on wet soil, so an old driveway that was built thinner is the one most likely to move.</p>"
            f"<p>If sunken areas are local, say one wheel track or a patch by a downspout, releveling is realistic. {post('why-pavers-sink-in-florida', 'Why pavers sink in Florida')} walks through the causes, and the cause tells you whether a fix will last. If the dip is everywhere, the base is the problem and restoring the surface only postpones it.</p>"),
        sec("What Checklist Helps You Decide?",
            "<p>Walk the pavement and mark each item. A few ticks in the \"restore\" column is the usual answer; several in \"replace\" means a rebuild.</p>"
            + table("Restore or replace: what to look for", ["What you see", "Points toward", "Why"],
                    [["Faded color, stains, algae, empty joints", "Restore", "Surface only; cleaning, re-sanding and sealing handle it"],
                     ["One or two sunken patches under 10% of the area", "Restore (relay)", "Lift, rebuild base, relay the same pavers"],
                     ["Over a third of the field is dipping or rutted", "Replace", "A base failure across the area; spot fixes won't hold"],
                     ["Several cracked or broken units", "Restore if scattered", "Swap individual pavers; clustered cracking means the base"],
                     ["Cracked units across the vehicle lanes", "Replace, with thicker units", "Likely too thin for the load"],
                     ["Edges spreading, joints opening at borders", "Restore if the restraint can be rebuilt", "ICPI says edge restraint is required around the perimeter"],
                     ["Roots lifting the field", "Depends on the tree", "A relay won't last if the root is still growing"],
                     ["Discontinued color, large replacement area", "Relay what you have", "Matching new units to old can be hard"],
                     ["Water standing after rain", "Fix drainage either way", "Neither option works over a wet base"]],
                    "A guide, not a diagnosis. A site visit decides.")
            + f"<p>On the roots row, {post('tree-roots-under-driveway-florida', 'tree roots under a driveway')} covers what can be done when a living tree is the cause.</p>"),
        sec("Are Your Pavers Too Thin for the Traffic They Carry?",
            f"<p>Pavers that were laid at 60 mm (2⅜ in.) are fine for a home driveway; ICPI's Tech Spec 2 says units for pedestrian areas and driveways with limited vehicle use are 60 mm and that streets and industrial pavement should be at least 80 mm (3⅛ in.). "
            f"A 60 mm driveway that now sees a loaded truck, a boat trailer or an RV may crack along the wheel path, and restoring it won't change the thickness.</p>"
            f"<p>Measure by looking at an exposed edge, or lifting one unit at a border. If cracked units are in the lanes where heavy vehicles actually drive, and the base also dips, replacing with a thicker unit and a base built for the load is the rebuild worth paying for. If the cracking is occasional and local, replace the broken units and move on.</p>"),
        sec("What Does Relaying Pavers Mean?",
            "<p>Relaying means lifting the existing pavers in a problem area, stacking and keeping them in order, rebuilding the base and bedding sand, and laying the same units back. It's the middle path between a clean-and-seal and a full replacement. It keeps the look, avoids a color mismatch and cuts the material bill.</p>"
            + steps([("Mark and lift.", "Pull the pavers in the failed area and a margin around it, keeping the pattern."),
                     ("Fix the cause.", "Remove the soft base, correct the drainage, and cut back or deal with roots if they're the reason."),
                     ("Rebuild the base.", "Add and compact aggregate in lifts, then screed about 1 inch of bedding sand."),
                     ("Relay and re-sand.", "Set the pavers back, compact, sweep in joint sand and compact again. Seal later, once the surface is dry and clean.")])
            + f"<p>Spare units help. A few leftover pavers from the original job, or units pulled from a spot that's rarely seen, make good fillers for a broken one. Without any, the nearest match may not blend, and that's the one case where a larger replacement can look better than a spot repair.</p>"),
        sec("How Do Restore and Replace Costs Compare?",
            f"<p>As of {'November 2026'}, Florida market ranges run about {price('paver-restoration')} {per('paver-restoration')} for restoration work, {price('paver-patio')} {per('paver-patio')} for a new paver patio and {price('paver-driveway')} {per('paver-driveway')} for a new paver driveway. Those figures don't change with the city; access, demolition, drainage and the base condition move the real number.</p>"
            + table("Market ranges, Florida", ["Work", "Range", "Unit"],
                    [["Restoration (releveling, repairs)", price("paver-restoration"), per("paver-restoration")],
                     ["New paver patio", price("paver-patio"), per("paver-patio")],
                     ["New paver driveway", price("paver-driveway"), per("paver-driveway")]],
                    "Ranges are market figures from published pricing, not quotes.")
            + f"<p>Say you have a 600-square-foot driveway with one sunken 60-square-foot wheel track. Relaying that patch sits in the restoration range; replacing all 600 sq ft sits in the new-driveway range. If the base is failing across the whole drive, though, the restoration price only buys a short delay. Full figures are on the {a('/paver-driveway-cost/', 'paver driveway cost page')}, and the new-build options are on the {svc('paver-driveways', 'paver driveway')} and {svc('paver-patios', 'paver patio')} pages.</p>"),
        sec("Do You Need HOA Approval to Restore or Replace?",
            f"<p>Often, if the look changes. Restoring the same pavers in the same color and pattern is often treated as maintenance; a new color, a different pattern, a wider footprint or a different material usually goes to the architectural review committee first. "
            f"The HOA's own documents decide, so read them before ordering anything, and see {post('hoa-approval-for-pavers-and-concrete', 'how HOA approval works for pavers and concrete')} for the process. Ask the association whether relaying counts as maintenance in writing, and keep the answer.</p>"),
        sec("Next Step",
            f"<p>We'll walk the pavement and tell you which side of the line it's on. Call Kissimmee & Greater Orlando at {tel('orlando')} or Sarasota at {tel('sarasota')}, or {contact('send photos through the form')}.</p>"),
    ])
    faqs = [
        faq("How many broken pavers is too many to just swap out?",
            "Scattered breaks are normal wear and can be swapped. When broken units cluster in one area, or keep returning after replacement, the base underneath is moving and the real fix is relaying that area."),
        faq("Can pavers be reused after they're lifted?",
            "Yes, if they're intact. Pavers are stacked in order, the base is rebuilt and the same units go back down, which keeps the color match. Chipped or cracked ones get replaced from spares."),
        faq("Will restoring my pavers fix a puddle that forms after rain?",
            "Only if the puddle comes from a local dip. A reliable fix levels the area and corrects where the water goes. If the whole surface is flat, drainage work comes before any cosmetic step."),
        faq("What if I can't find pavers that match my old ones?",
            "Reuse units from a hidden area, such as under a planter or at an edge, to fill the visible spots. If a large area needs new material, a border or a different field can look intentional."),
        faq("Does the age of the pavers decide whether to restore them?",
            "Not by itself. Concrete pavers can outlast the base and sealer under them. Condition decides: shape of the surface, soundness of the units, and whether the base moved."),
        faq("Should I seal pavers right after they're relaid?",
            "Wait until the surface is clean, dry and the joint sand has settled. Sealing too early can trap moisture. The same dry-surface rule applies as on new work."),
    ]
    return page("/blog/restore-or-replace-old-pavers/", "post",
                "Restore or Replace Old Pavers? A Decision Checklist",
                "Restore or replace old pavers? Checklist, decision table and cost ranges for Florida driveways and patios, including relaying and HOA notes, as of November 2026.",
                "Restore or Replace? How to Tell if Old Pavers Can Be Saved",
                capsule(f"Old pavers can usually be saved when the units are sound and the problem is faded color, stains or one or two sunken patches. As of November 2026, Florida market ranges run about {price('paver-restoration')} {per('paver-restoration')} to restore, against {price('paver-driveway')} {per('paver-driveway')} for a new paver driveway; widespread base failure in Kissimmee or Sarasota points to replacement."),
                body, faqs=faqs,
                sources=["icpi-ts2", "icpi-ts3", "icpi-ts5", "homeguide-driveway-repair", "homeguide-driveway-pavers", "homeguide-paver-patio"],
                related=[("/paver-restoration/", "Paver restoration"), ("/paver-driveways/", "Paver driveways"),
                         ("/paver-patios/", "Paver patios"), ("/blog/why-pavers-sink-in-florida/", "Why pavers sink"),
                         ("/paver-driveway-cost/", "Paver driveway cost")],
                crumbs=[("Blog", "/blog/")], published="2026-11-17", service="paver-restoration", image=None, form=False)


def get_pages():
    return [p_paver_sealer_turned_white_or_cloudy(), p_restore_or_replace_old_pavers()]
